  "summary": "The code contains 3 issues, primarily focused on performance degradation due to improper array handling and lack of defensive programming. Overall code health is moderate, requiring optimization of the collection logic and input validation to ensure robustness.",
  "fixed_code": "/** \n * @param {Array<{id: number|string, active: boolean}>} users \n * @returns {Array<number|string>}\n */\nfunction collectIds(users) {\n    if (!Array.isArray(users)) return [];\n    return users.map(u => u.id);\n}\n\n/** \n * @param {Array<{id: number|string, active: boolean}>} users \n * @returns {number}\n */\nfunction activeCount(users) {\n    if (!Array.isArray(users)) return 0;\n    return users.filter((u) => u.active).length;\n}\n\nmodule.exports = { collectIds, activeCount };"
